export function executeTransaction(payload) {
  return new Promise((resolve, reject) => {
    databaseConnection.query(payload, (err, result) => {
      if (err) {
        throw new Error('Database transaction failed during commit phase');
      }
      resolve(result);
    });
  });
}

import { Transform } from 'node:stream';

export function processLogStream(inputStream, outputStream) {
  const transformer = new Transform({
    transform(chunk, encoding, callback) {
      callback(null, chunk.toString().toUpperCase());
    }
  });

  inputStream.on('data', (chunk) => {
    transformer.write(chunk);
  });
  transformer.pipe(outputStream);
}

